<script>const button=document.getElementById('printButton');const waitForImages=()=>Promise.all([...document.images].map(img=>img.complete?Promise.resolve():new Promise(resolve=>{img.addEventListener('load',resolve,{once:true});img.addEventListener('error',resolve,{once:true});})));async function prepare(){if(document.fonts?.ready)await document.fonts.ready;await waitForImages();button.disabled=false;button.textContent='چاپ محصولات'}button.addEventListener('click',async()=>{button.disabled=true;await prepare();window.print();button.disabled=false});prepare();</script></body></html>
